package com.ecommerce.cart; import com.ecommerce.product.*; import com.ecommerce.user.*; import com.ecommerce.common.ApiException; import jakarta.validation.constraints.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/cart") public class CartController {record Add(@NotNull UUID productId,@Min(1) int quantity){} private final CartRepository carts; private final ProductRepository products; private final UserRepository users; public CartController(CartRepository c,ProductRepository p,UserRepository u){carts=c;products=p;users=u;} @GetMapping Cart cart(Authentication a){return get(a);} @PostMapping("/items") Cart add(@RequestBody @jakarta.validation.Valid Add x,Authentication a){Cart c=get(a);Product p=products.findById(x.productId()).orElseThrow(()->new ApiException("Product not found"));if(p.getStatus()!=Product.Status.ACTIVE)throw new ApiException("Product not available");CartItem i=c.getItems().stream().filter(z->z.getProduct().getId().equals(p.getId())).findFirst().orElse(null);if(i==null){i=new CartItem();i.setCart(c);i.setProduct(p);i.setQuantity(x.quantity());c.getItems().add(i);}else i.setQuantity(i.getQuantity()+x.quantity());return carts.save(c);} @DeleteMapping("/items/{id}") void remove(@PathVariable UUID id,Authentication a){Cart c=get(a);c.getItems().removeIf(i->i.getId().equals(id));carts.save(c);} private Cart get(Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return carts.findByUserId(u.getId()).orElseGet(()->{Cart c=new Cart();c.setUser(u);return carts.save(c);});}}
